def check_numeric_column(filepath, column_name):
    """Check if a specific column contains numeric values."""
    if not os.path.exists(filepath):
        return False, "File does not exist"

    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)

        if column_name not in reader.fieldnames:
            return False, f"Column '{column_name}' not found"

        for i, row in enumerate(reader, start=2):  # Start at 2 (1 for header)
            try:
                float(row[column_name])
            except (ValueError, TypeError):
                return False, f"Non-numeric value in column '{column_name}' at row {i}"

        return True, f"Column '{column_name}' contains numeric values"


